import {a2Lessons} from './a2.js?v=d9b04d29540c';
import {lessonQuizEnglish} from './bilingual.js?v=d9b04d29540c';
// Todo el material didáctico de estas unidades es original. Referencias oficiales al final.
export const section=(title,text,examples=[])=>({title,text,examples});
export const question=(prompt,correct,others,why)=>({prompt,options:[correct,...others],answer:0,why});
const s=section,q=question;
export const lessons=[
{id:'b1-base',level:'B1',title:'Construir frases con seguridad',tag:'Base y precisión',minutes:35,
goal:'Describir personas, lugares y situaciones sin traducir palabra por palabra.',help:'Spanish usually omits subject pronouns. Ser classifies; estar presents a state or locates something. Do not reduce this to permanent versus temporary.',
sections:[
s('Ser estar y haber','Ser identifica, clasifica y atribuye características: profesión, origen, material o valoración general. Estar sitúa personas y objetos y presenta estados o resultados. La oposición no equivale siempre a permanente y temporal: «está muerto» y «es joven» muestran por qué esa regla falla. Los acontecimientos se localizan con ser. Haber introduce la existencia de algo y es impersonal en este uso: hay, había, hubo y habrá no concuerdan con el nombre.', ['Soy de Florida; ahora estoy en España.','El concierto es en la plaza; la plaza está en el centro.','Había muchas personas, no «habían muchas personas».','Es aburrido = provoca aburrimiento. Está aburrido = siente aburrimiento.']),
s('Género artículos y concordancia','Aprende cada sustantivo con artículo y un ejemplo. El problema, la mano y la foto no siguen una regla simple basada en la última letra. Ante un sustantivo femenino singular que empieza por /a/ tónica se usa el: el agua fría; en plural, las aguas frías. El adjetivo sigue siendo femenino. Compara «soy profesora» con «es una profesora excelente». Usa el artículo para hablar de una clase general: me gusta el café. Para una cantidad indeterminada, «quiero café».',['El agua está fría.','La gente es amable; las personas son amables.','Tengo una duda sobre el horario.']),
s('Orden natural y preguntas','El español permite mover información, pero empezar por sujeto, verbo y complementos facilita la claridad. No necesitas repetir yo en cada frase. «Yo» resulta útil para contrastar: tú prefieres la playa; yo prefiero la montaña. En las preguntas no añadas un auxiliar equivalente a do. Usa entonación y palabras interrogativas. En escritura, abre y cierra interrogaciones y exclamaciones.',['¿Dónde vive tu hermana?','¿Qué significa esta palabra?','Me encanta España, pero todavía me cuesta entender algunas bromas.'])],
chunks:['me cuesta + infinitivo','tengo una duda sobre','depende de','lo que más me gusta es'],
quiz:[q('Indica dónde se celebra el evento: La fiesta ___ en casa de Ana.','es',['está','hay'],'La fiesta es un acontecimiento: su lugar se expresa con ser.'),q('Presenta la existencia de dos bibliotecas, sin identificarlas antes: En mi barrio ___ dos bibliotecas.','hay',['están','son'],'Haber presenta la existencia; estar localizaría bibliotecas ya identificadas.'),q('Elige la frase correcta.','El agua está fría.',['El agua está frío.','La agua está fría.'],'El cambia por la /a/ tónica, pero agua es femenino.'),q('Ayer ___ muchas personas en la estación.','había',['habían','habías'],'Haber existencial es impersonal; aquí se mantiene en singular.'),q('Soy ___ y trabajo en un colegio.','profesora',['profesoras','una profesor'],'La profesión normalmente aparece sin artículo en esta construcción.'),q('Esta película me hace bostezar. Es ___.','aburrida',['aburrido','aburrirse'],'Describe la película y concuerda con el sustantivo femenino.')],
speak:'Describe tu barrio a alguien que quiere mudarse: qué hay, dónde están los lugares importantes y cómo son. Compara después tu barrio actual con uno de Florida.',write:'Escribe una presentación de 100–130 palabras para una persona que va a visitarte. Incluye tu origen, tu situación actual, el lugar de un evento y lo que hay cerca de casa.',model:'Soy de Florida y ahora vivo en España. Mi barrio es bastante tranquilo, aunque los fines de semana hay mucho movimiento. La estación está a diez minutos de casa. Este sábado hay una fiesta: es en la plaza principal. Me gusta vivir aquí porque puedo ir andando a casi todos los sitios, pero todavía me cuesta entender a algunas personas cuando hablan muy deprisa.'},
{id:'b1-presente',level:'B1',title:'Presente y acciones en marcha',tag:'Verbos cotidianos',minutes:40,
goal:'Hablar de hábitos, cambios y acciones actuales con verbos frecuentes.',help:'Use the simple present for habits. Estar + gerund describes an action in progress; English uses its progressive form in more situations than Spanish.',
sections:[
s('Presente regular e irregular','Para -ar: hablo, hablas, habla, hablamos, habláis, hablan. Para -er: como, comes, come, comemos, coméis, comen. Para -ir: vivo, vives, vive, vivimos, vivís, viven. Los cambios de raíz suelen desaparecer en nosotros y vosotros: pienso/pensamos; puedo/podemos; pido/pedimos. Practica también tengo, vengo, salgo, hago, digo, sé y conozco. Aprender solo el infinitivo no permite recuperar la forma al hablar. Saber y conocer no se dividen siempre en información frente a personas: sé la respuesta y conozco la respuesta son posibles. Aprende cada verbo en varias frases.',['Trabajo desde casa los lunes.','No sé la respuesta, pero conozco a alguien que puede ayudarte.','¿A qué hora vuelves?']),
s('Reflexivos y verbos como gustar','En levantarse, el pronombre acompaña a quien realiza la acción: me levanto, te levantas, se levanta. En gustar, el sujeto es lo que produce la sensación: me gusta el café; me gustan las ciudades pequeñas. El pronombre indica a quién le gusta. Se pueden añadir a mí o a ella para contrastar o aclarar, manteniendo me/le. Otros patrones útiles son me interesa, me preocupa, me apetece y me falta.',['A ella le gustan los idiomas.','Nos preocupa el precio del alquiler.','Me falta una página para terminar.']),
s('Perífrasis de uso frecuente','Estar + gerundio enfoca una acción en desarrollo: estoy leyendo. No lo uses por sistema en hábitos: trabajo en una oficina. Seguir + gerundio indica continuidad; llevar + tiempo + gerundio, duración hasta ahora; acabar de + infinitivo, pasado reciente; volver a + infinitivo, repetición. El gerundio se forma con -ando o -iendo; aprende leyendo, durmiendo, pidiendo y yendo.',['Llevo dos años estudiando español.','Sigo buscando una solución.','Acabo de llegar y voy a preparar la cena.'])],
chunks:['llevo tiempo intentando','acabo de darme cuenta','me apetece','vuelvo a intentarlo'],
quiz:[q('Nosotras ___ salir antes de las ocho.','podemos',['puedemos','pueden'],'En nosotros no aparece el diptongo de puedo.'),q('A mi pareja le ___ las películas españolas.','gustan',['gusta','gustáis'],'El sujeto plural las películas exige gustan.'),q('Ahora mismo ___ un correo.','estoy escribiendo',['soy escribiendo','estoy escribir'],'Estar + gerundio presenta la acción en curso.'),q('Hace dos minutos que he llegado: ___ llegar.','acabo de',['sigo','llevo'],'Acabar de + infinitivo expresa una acción reciente.'),q('Ayer empecé el libro y todavía no he terminado: ___ leyendo.','sigo',['vuelvo de','soy'],'Seguir + gerundio indica que continúa la acción.'),q('Usa saber en presente, yo: Yo ___ la respuesta a la pregunta.','sé',['conozco','sabo'],'La instrucción pide la forma de saber: sé, con tilde. Conozco la respuesta también es correcto, pero pertenece a conocer; por eso aquí se indica qué verbo practicar.')],
speak:'Cuenta un día normal y después explica qué estás haciendo de forma diferente esta semana. Incluye una cosa que llevas tiempo intentando y algo que acabas de hacer.',write:'Escribe 120 palabras sobre tus hábitos de aprendizaje. Alterna hábitos y acciones en curso y utiliza al menos tres perífrasis.',model:'Normalmente estudio por la tarde, pero esta semana estoy practicando antes de trabajar. Me gustan las conversaciones cortas porque puedo concentrarme mejor. Llevo varios meses intentando hablar con más soltura y sigo buscando maneras de practicar. Acabo de escuchar una entrevista y voy a resumirla en voz alta. Si no recuerdo una palabra, intento explicarla de otra manera.'},
{id:'b1-pasados',level:'B1',title:'Contar historias en pasado',tag:'Indefinido e imperfecto',minutes:45,
goal:'Combinar acontecimientos y contexto para contar una experiencia con claridad.',help:'The imperfect sets a scene or describes a past habit. The preterite presents an event as a bounded whole. Both can describe long or short situations.',
sections:[
s('Acontecimiento y fondo','El indefinido presenta un hecho delimitado: fui, llegué, conocí, trabajé allí dos años. El imperfecto muestra el interior de una situación sin enfocarse en sus límites: era, tenía, vivía, hacía. Se usa para hábitos, contexto y acciones en desarrollo. No elijas solo por duración: «viví allí veinte años» está delimitado; «cuando abrí la puerta, dormía» presenta una acción en curso.',['Ayer hacía frío y decidimos quedarnos en casa.','Cuando vivía en Florida, iba mucho a la playa.','Viví en España dos años y después regresé.']),
s('Formas que necesitas recuperar rápido','Indefinido regular: hablé/hablaste/habló/hablamos/hablasteis/hablaron; comí/comiste/comió/comimos/comisteis/comieron. Imperfecto: hablaba y comía; las irregularidades principales son era, iba y veía. En indefinido aprende fui, tuve, estuve, hice, dije, pude, quise, vine, puse y supe. Los verbos en -ir pueden cambiar en tercera persona: pidió/pidieron, durmió/durmieron.',['Ayer fui al centro y tuve que esperar.','No pude entrar porque no tenía entrada.','Cuando lo supe, se lo dije a mi hermana.']),
s('El punto de vista cambia el significado','«Conocía a Marta» describe una relación previa; «conocí a Marta» presenta el primer encuentro. «Sabía la noticia» describe conocimiento; «supe la noticia» presenta el momento de enterarse. «Quería hablar» presenta una intención; «quise hablar» la delimita, y no implica por sí solo que la conversación ocurriera. Organiza una historia con al principio, mientras, de repente, entonces y al final.',['Mientras esperaba el autobús, recibí una llamada.','No conocía la ciudad, así que pedí ayuda.','Al final encontramos el restaurante y cenamos allí.'])],
chunks:['de repente','mientras esperaba','al principio','al final resultó que'],
quiz:[q('Presenta el sueño como una acción en curso cuando llamaron: Mientras yo ___, alguien llamó a la puerta.','dormía',['dormí','dormiré'],'Dormía muestra el sueño desde dentro, como fondo de la llamada. La instrucción pide esa perspectiva; mientras no obliga por sí solo a usar siempre imperfecto.'),q('Presenta la visita como un acontecimiento terminado, en pretérito indefinido: Ayer ___ al médico a las nueve y salí a las diez.','fui',['iba','voy'],'Se presenta una visita delimitada.'),q('Describe una costumbre de infancia en imperfecto: De pequeña, todos los veranos ___ a la playa.','iba',['fui','he ido'],'Iba presenta una costumbre como fondo. Fui también puede resumir una serie terminada de visitas en otro relato; aquí se solicita la perspectiva habitual en imperfecto.'),q('Cuenta el primer encuentro como un hecho terminado: Ayer por primera vez ___ a la hermana de Ana.','conocí',['conocía','conozco'],'Conocí enfoca el encuentro inicial.'),q('Viví en Madrid veinte años. ¿Por qué indefinido?','El hablante presenta un período delimitado.',['Porque fue un período corto.','Porque Madrid ya no existe.'],'La elección depende del punto de vista, no de cuánto duró.'),q('El pretérito indefinido de hacer, ella, en «ella ___ la cena ayer» es…','hizo',['hizó','hacía siempre'],'Hizo es irregular y no lleva tilde.')],
speak:'Cuenta una situación en la que un plan salió mal. Primero sitúa dónde estabas y qué hacías; después cuenta tres acontecimientos y cómo terminó. Tu compañero pregunta qué ocurrió antes y después.',write:'Escribe una anécdota de 140 palabras. Subraya mentalmente tres verbos de fondo y tres acontecimientos. Cambia un tiempo y explica cómo cambia la perspectiva.',model:'El sábado queríamos pasar el día fuera. Hacía buen tiempo y teníamos todo preparado, pero cuando llegamos a la estación vimos que el tren se había cancelado. Mientras buscábamos otra opción, una amiga nos llamó. Nos propuso ir a un pueblo cercano en coche. Al principio me daba pena cambiar el plan; al final pasamos una tarde estupenda.'},
{id:'b1-perfectos',level:'B1',title:'Conectar el pasado con el presente',tag:'Perfecto y pluscuamperfecto',minutes:35,
goal:'Explicar experiencias, resultados y acontecimientos anteriores a otros.',help:'The present perfect varies across Spanish-speaking regions. A speaker may say hoy fui where another says hoy he ido. Learn the viewpoint and the local pattern without treating one variety as wrong.',
sections:[
s('Pretérito perfecto compuesto','Se forma con he, has, ha, hemos, habéis, han + participio. Los regulares terminan en -ado o -ido; aprende hecho, dicho, visto, escrito, puesto, vuelto, abierto y roto. El participio con haber no concuerda: hemos escrito dos cartas. En buena parte de España es habitual usar el perfecto para períodos vinculados al presente y experiencias hasta ahora. La distribución con el indefinido cambia entre regiones y contextos.',['Esta semana he hablado más español.','Nunca he vivido en una ciudad tan grande.','Hoy he ido al mercado / Hoy fui al mercado, según variedad y enfoque.']),
s('Anterioridad en el pasado','El pluscuamperfecto combina había, habías, había, habíamos, habíais, habían + participio. Sitúa un hecho antes de otro punto pasado: cuando llegué, ya habían cenado. Aquí habían es correcto porque funciona como auxiliar con sujeto plural; se distingue de «había muchas personas», uso existencial impersonal. No lo uses si no necesitas mostrar anterioridad.',['No tenía hambre porque había comido antes.','Cuando llamé, ya habían salido.','Nunca había probado ese plato hasta aquel viaje.']),
s('Marcadores y precisión','Ya suele presentar un resultado alcanzado; todavía no, algo pendiente. Alguna vez pregunta por experiencias; desde y desde hace señalan el comienzo o duración de una situación que continúa. Hace + tiempo localiza un hecho anterior. Elige una referencia temporal antes de conjugar para evitar saltos incoherentes.',['Vivo aquí desde 2024.','Vivo aquí desde hace dos años.','Me mudé hace dos años.'])],
chunks:['todavía no he','ya había','desde hace','hasta ahora'],
quiz:[q('Nosotras hemos ___ dos cartas.','escrito',['escritas','escribido'],'Con haber el participio es invariable; escrito es irregular.'),q('Cuando llegué, mis amigas ya ___ salido.','habían',['había','han de'],'El auxiliar concuerda con mis amigas y marca anterioridad.'),q('Vivo aquí ___ dos años.','desde hace',['hace de','desde'],'Desde hace introduce una duración hasta ahora.'),q('Me mudé ___ dos años.','hace',['desde','desde hace que'],'Hace localiza un acontecimiento terminado.'),q('Elige la frase correcta.','He visto esa película.',['He veído esa película.','He vista esa película.'],'El participio de ver es visto y no concuerda con película.'),q('¿«Hoy fui al mercado» siempre es incorrecto?','No; depende de la variedad y del enfoque.',['Sí, en todo el español.','Solo es correcto en futuro.'],'El perfecto y el indefinido presentan variación regional.')],
speak:'Cuenta tres cosas que has aprendido viviendo en España. Después explica una experiencia que nunca habías tenido antes de mudarte.',write:'Escribe un balance de 130 palabras. Distingue lo que has conseguido hasta ahora, lo que todavía no has hecho y lo que ya sabías antes de empezar.',model:'Desde que empecé a practicar con regularidad, he aprendido a pedir aclaraciones sin cambiar al inglés. Todavía no he conseguido entender todas las conversaciones de grupo. Antes de vivir en España ya había estudiado algo de gramática, pero nunca había utilizado el idioma cada día. Ahora me siento más cómoda cuando tengo que resolver un problema cotidiano.'},
{id:'b1-futuro',level:'B1',title:'Planes deseos y posibilidades',tag:'Futuro y condicional',minutes:40,
goal:'Hablar de planes, predicciones, hipótesis y peticiones corteses.',help:'Spanish uses the present for scheduled future events. The future can also express a guess about now; the conditional can soften a request.',
sections:[
s('Elegir cómo hablar del futuro','Ir a + infinitivo expresa una intención o un plan: voy a estudiar. El presente también sitúa acontecimientos futuros con un marcador: mañana trabajo. El futuro simple presenta predicciones y decisiones, y puede expresar conjeturas actuales: estará en casa = probablemente está en casa. No todos los futuros ingleses con will se traducen de la misma forma.',['Mañana cenamos con tu familia.','Voy a preparar la conversación antes de salir.','No responde; estará ocupada.']),
s('Formar futuro y condicional','El futuro añade -é, -ás, -á, -emos, -éis, -án al infinitivo. El condicional añade -ía, -ías, -ía, -íamos, -íais, -ían. Comparten raíces irregulares: tendr-, podr-, har-, dir-, saldr-, vendr-, pondr-, querr- y sabr-. El condicional permite imaginar resultados, expresar deseos y suavizar peticiones. No se construye «si tendría» para una condición hipotética ordinaria.',['Me gustaría hablar con más soltura.','¿Podrías repetir la última parte?','Si tengo tiempo, iré; si tuviera tiempo, iría.']),
s('Obligación consejo y preferencia','Tener que + infinitivo presenta una obligación personal; hay que + infinitivo, una necesidad general; deber + infinitivo, obligación o recomendación según contexto. Deber de puede expresar probabilidad: deben de ser las ocho. Practica preferencias con prefiero, preferiría y me gustaría. Explica razones para convertir una lista de planes en conversación.',['Hay que reservar antes de ir.','Tendría que organizar mejor mi tiempo.','Preferiría salir temprano porque habrá menos tráfico.'])],
chunks:['me gustaría','si tengo tiempo','¿podrías repetir?','preferiría que'],
quiz:[q('Mañana yo ___ más tiempo.','tendré',['teneré','tendría ayer'],'Tener usa la raíz tendr- en futuro.'),q('Una petición cortés es…','¿Podrías hablar un poco más despacio?',['¿Poderías hablar?','¿Puedes hablando?'],'Podrías suaviza la petición y va seguido de infinitivo.'),q('Si mañana tengo tiempo, ___ a verte.','iré',['iría ayer','fuera'],'Con una condición abierta en presente puede aparecer un resultado futuro.'),q('No sé dónde está; ___ en casa.','estará',['será','estuvieron'],'Futuro de conjetura para una ubicación actual.'),q('Para entrar al museo ___ reservar.','hay que',['hay de','está que'],'Hay que + infinitivo expresa una necesidad general.'),q('Me ___ vivir cerca del mar.','gustaría',['gustaré','gustarían yo'],'El condicional expresa un deseo; vivir funciona como sujeto singular.')],
speak:'Organiza un fin de semana con tu compañero. Propón tres alternativas, explica qué preferirías y responde a un cambio de presupuesto o de tiempo.',write:'Escribe un mensaje de 120 palabras proponiendo un plan. Incluye fecha, dos alternativas, una condición abierta y una petición cortés.',model:'El sábado podríamos pasar el día en la costa. Me gustaría salir temprano para aprovechar la mañana. Si hace buen tiempo, iremos a la playa; si llueve, podemos visitar el museo. Habría que reservar el restaurante antes del viernes. ¿Podrías mirar los horarios del tren? Yo me encargaré de buscar un sitio para comer.'},
{id:'b1-pronombres',level:'B1',title:'Pronombres sin perder el hilo',tag:'Lo la le y se',minutes:45,
goal:'Retomar información con pronombres y entender a quién se refiere cada uno.',help:'Direct objects answer what or whom; indirect objects often indicate the recipient. Learn the full verb pattern, not only an English translation.',
sections:[
s('Objeto directo e indirecto','El objeto directo se sustituye por lo, la, los o las: compro el libro → lo compro. El indirecto por le o les: doy el libro a Ana → le doy el libro. Me, te, nos y os sirven para ambos tipos según el verbo. La a personal aparece con personas identificadas como objeto directo: vi a Ana → la vi. No toda a introduce un indirecto. En ciertas variedades se usa le para un hombre singular como objeto directo; aprende a reconocerlo sin perder el patrón básico.',['Vi a tu hermana y la saludé.','Le envié un mensaje a tu hermana.','La llamé para contarle la noticia.']),
s('Dos pronombres y colocación','Cuando le/les va antes de lo/la/los/las, se convierte en se: le di el libro → se lo di. Ese se no indica por sí solo singular o plural; el contexto aclara a quién. Ante un verbo conjugado van delante: se lo expliqué. Con infinitivo o gerundio pueden ir unidos o delante del auxiliar: voy a explicárselo / se lo voy a explicar. Con imperativo afirmativo se unen; con negativo van delante.',['Se lo voy a contar / Voy a contárselo.','Estoy leyéndolo / Lo estoy leyendo.','Dímelo, pero no se lo digas a nadie.']),
s('Evitar referencias ambiguas','No acumules pronombres si el referente resulta confuso. Repite un nombre cuando cambia el destinatario. Lo también sustituye una idea completa: no lo sabía = no sabía eso. Con verbos como gustar, le identifica a la persona que siente: a Ana le gusta el libro. Aprende secuencias completas y úsalas en voz alta con un objeto real.',['¿Sabías que cambió el horario? No, no lo sabía.','Le presté el libro a Marta; después Ana me pidió otra novela.','¿Puedes explicármelo con un ejemplo?'])],
chunks:['no lo sabía','se lo dije','¿me lo puedes explicar?','te lo paso luego'],
quiz:[q('Compré las entradas. → ___ compré.','Las',['Les','Los'],'Entradas es objeto directo femenino plural.'),q('Di el libro a Ana. → ___ di.','Se lo',['Le lo','La le'],'Le cambia a se ante lo; lo sustituye el libro.'),q('Vi a tu hermana. → ___ vi.','La',['Le lo','Se la'],'La a personal no convierte a tu hermana en indirecto.'),q('Elige una colocación correcta.','Voy a contárselo.',['Voy a se lo contar.','Voy contarlo se.'],'Los pronombres pueden unirse al infinitivo con tilde cuando corresponde.'),q('No sabía que habías llegado. → No ___ sabía.','lo',['la','le'],'Lo puede representar el contenido de una proposición.'),q('Elige el imperativo negativo correcto.','No me lo cuentes.',['No cuéntamelo.','No lo me cuentes.'],'En imperativo negativo los pronombres preceden al verbo.')],
speak:'Explica qué harás con cinco objetos: una foto, unas entradas, un libro, un regalo y un mensaje. Di a quién se los darás y por qué. Tu compañero cambia el destinatario.',write:'Escribe un diálogo de diez intervenciones sobre un objeto perdido y encontrado. Incluye lo/la/las, le y se lo, con referentes claros.',model:'—¿Has encontrado las entradas? —Sí, las dejé en la mesa. —¿Se las has dado a Ana? —Todavía no; se las voy a dar esta tarde. —Dile que me llame cuando las tenga. —Se lo diré. Por cierto, ¿puedes enviarme la dirección? —Claro, te la paso ahora.'},
{id:'b1-preposiciones',level:'B1',title:'Relacionar ideas con precisión',tag:'Por para y preposiciones',minutes:40,
goal:'Explicar motivos, fines, duración, destinos y relaciones habituales.',help:'Por often introduces a cause or a route; para often introduces a purpose or recipient. Neither has a single English equivalent.',
sections:[
s('Motivo y finalidad','Por puede expresar causa, intercambio, recorrido, medio o agente. Para puede expresar finalidad, destinatario, plazo o punto de vista. «Estudio por mi trabajo» presenta el trabajo como motivo; «estudio para conseguir un trabajo» presenta una meta. Pregunta qué relación quieres construir, en lugar de traducir for.',['Gracias por ayudarme.','Estudio para hablar con tu familia.','Paseamos por el centro.','Este regalo es para ti.']),
s('Tiempo y movimiento','Hasta señala un límite; desde, un origen; durante, el desarrollo de un período. Para el viernes expresa un plazo; el viernes localiza un día. Ir a señala destino; estar en, ubicación; salir de, origen; pasar por, recorrido. La duración con por existe en algunas variedades, pero «durante dos semanas» o «dos semanas» sirve como patrón inicial claro.',['Trabajo hasta las seis.','Tengo que terminarlo para el viernes.','Salgo de casa, paso por la estación y voy al centro.']),
s('Aprender el régimen del verbo','Algunos verbos seleccionan una preposición: depender de, pensar en, soñar con, acordarse de, confiar en y acostumbrarse a. Recordar algo y acordarse de algo expresan ideas próximas con construcciones distintas. Antes de un infinitivo conserva la preposición: estoy acostumbrada a vivir aquí. Del y al son contracciones de de/el y a/el.',['Depende del horario.','Me acuerdo de aquella conversación.','Pienso en cambiar de trabajo.','Estoy aprendiendo a expresarme mejor.'])],
chunks:['depende de','me acuerdo de','estoy acostumbrada a','gracias por'],
quiz:[q('Expresa el objetivo del estudio: Estudio español ___ hablar con tus amigos.','para',['por','desde'],'Para introduce aquí el objetivo: con el fin de hablar. Por puede expresar un motivo en otros contextos; la instrucción especifica la relación que debes construir.'),q('Gracias ___ venir.','por',['para','a'],'Gracias por introduce el motivo del agradecimiento.'),q('Me acuerdo ___ ese día.','de',['a','en'],'Acordarse selecciona la preposición de; el patrón es acordarse de algo.'),q('El resultado depende ___ tiempo disponible.','del',['al','en el'],'Depender de + el se contrae en del.'),q('Estoy acostumbrada ___ hablar con ellos.','a',['de','por'],'Acostumbrarse a mantiene a delante de infinitivo.'),q('Entrega antes de que termine el viernes: entrégalo ___ el viernes.','para',['desde','durante'],'Para marca el plazo de entrega.')],
speak:'Explica por qué estudias español y para qué quieres utilizarlo. Da instrucciones para ir de tu casa a tres lugares y justifica un plazo.',write:'Escribe 130 palabras sobre un proyecto personal. Incluye motivo, meta, destinatario, plazo y tres verbos con preposición.',model:'Estoy preparando una visita para mis amigas. Vendrán por unos días y quiero organizar actividades para que conozcan la ciudad. El plan depende del tiempo, así que pienso en dos alternativas. Tengo que reservar para el viernes. Me acuerdo de un restaurante que les podría gustar y estoy acostumbrada a pedir mesa allí.'},
{id:'b1-describir',level:'B1',title:'Describir comparar y especificar',tag:'Relativos y comparación',minutes:40,
goal:'Elegir entre alternativas y describir algo aunque no recuerdes su nombre.',help:'Que identifies a person or thing. Spanish comparative patterns include más… que, tan… como and tanto… como. Commas distinguish identifying information from extra information.',
sections:[
s('Relativos para explicar palabras','Que retoma personas o cosas: la amiga que vive aquí; el libro que compré. Donde retoma lugares: la ciudad donde crecí. Usa preposición cuando la relación la exige: la persona con la que hablé, el tema del que hablamos. Esta estructura es una herramienta de fluidez: «es una cosa que sirve para…» te permite continuar sin la palabra exacta.',['Busco una tienda donde vendan material de dibujo.','Es la persona con la que viajé.','Es una herramienta que sirve para abrir botellas.']),
s('Comparativos y cantidad','Más/menos + adjetivo + que; tan + adjetivo + como; tanto/a/os/as + nombre + como; verbo + tanto como. Mejor y peor suelen sustituir más bueno y más malo en comparaciones ordinarias. Mayor y menor se usan en ciertos sentidos, pero más grande y más pequeño son naturales para tamaños físicos. Con números, «más de veinte» expresa superar una cantidad.',['Esta ciudad es más pequeña que Miami.','No tengo tanto tiempo como antes.','Hablas tan claro como ella.','Hay más de veinte participantes.']),
s('Matices descriptivos y puntuación','Un adjetivo puede cambiar de interpretación según su posición: una vieja amiga es una amiga de hace tiempo; una amiga vieja tiene edad avanzada. En escritura, las comas distinguen información identificadora de información añadida: «mis amigas que viven aquí» selecciona algunas; «mis amigas, que viven aquí,» añade información sobre todas las mencionadas. Empieza por descripciones concretas y después añade una valoración.',['Es una antigua compañera de trabajo.','Tiene menos habitaciones, pero está mejor comunicado.','El piso que vimos ayer tiene un balcón.'])],
chunks:['es una cosa que sirve para','en comparación con','lo mejor es que','la persona con la que'],
quiz:[q('Tengo ___ tiempo como tú.','tanto',['tan','tanta'],'Tiempo es sustantivo masculino singular.'),q('Ella es ___ paciente como su hermana.','tan',['tanto','más de'],'Tan modifica al adjetivo paciente.'),q('La persona ___ hablé trabaja aquí.','con la que',['que con','con que la'],'El verbo hablar con exige conservar con.'),q('En la sala hay ___ veinte personas; he contado veinticinco.','más de',['más que','tan'],'Más de introduce una cantidad superada.'),q('Una vieja amiga puede significar…','Una amiga de hace mucho tiempo.',['Una amiga necesariamente anciana.','Una amiga que vive lejos.'],'La posición de vieja puede aportar un sentido temporal a la relación.'),q('«Mis amigas que viven aquí» selecciona…','Las amigas que viven en este lugar.',['Siempre todas mis amigas.','Ninguna amiga.'],'La relativa sin comas restringe el grupo.')],
speak:'Compara dos lugares para vivir. Habla de tamaño, transporte, coste y ambiente. Describe un objeto sin decir su nombre para que tu compañero lo adivine.',write:'Escribe una comparación de 140 palabras entre dos opciones de viaje. Incluye comparativos, una relativa con preposición y una recomendación justificada.',model:'El primer alojamiento es más barato que el segundo, pero está más lejos del centro. No tiene tantas habitaciones como el otro, aunque la terraza es bastante grande. La propietaria con la que hablé fue muy amable. El segundo está mejor comunicado. Para una visita corta elegiría este último porque perderíamos menos tiempo en los desplazamientos.'},
{id:'b1-sonido',level:'B1',title:'Sonar clara y mantener la conversación',tag:'Pronunciación y reparación',minutes:35,
goal:'Hablar de manera comprensible y resolver bloqueos sin cambiar automáticamente al inglés.',help:'Aim for intelligibility, not an accent-free identity. Spanish vowels are relatively stable: avoid turning a clear vowel into an English-like diphthong.',
sections:[
s('Vocales acento y ritmo','Practica a, e, i, o, u manteniendo la calidad de cada vocal. En inglés muchas vocales átonas se reducen; en español una reducción excesiva puede ocultar palabras. Marca la sílaba tónica: hablo/habló; práctico/practico/practicó. Las palabras acabadas en vocal, n o s suelen ser llanas; las demás, agudas, salvo tilde. Los hiatos como país y día exigen atención. Divide por grupos de sentido y enlaza sin eliminar información.',['Quiero hablar / con más calma / y explicar mejor mis ideas.','Trabajo en casa → une las palabras sin pausas artificiales.','El público publicó una nota.']),
s('Sonidos que conviene observar','La h escrita no suele sonar; b y v no se distinguen como en inglés. R y rr pueden distinguir palabras como pero/perro; empieza con contrastes lentos y después frases. La j requiere un sonido posterior que cambia según la región. En parte de España se distingue s de c/z; en otras zonas hay seseo. Ambas realizaciones son válidas: prioriza entender distintas voces, no imitar una variedad a cualquier precio.',['pero / perro','caro / carro','vino / bien','hola / ahora']),
s('Pedir ayuda sin abandonar el turno','Una pausa no equivale a un fracaso. Aprende formas para ganar tiempo, comprobar comprensión y reformular. «A ver» o «déjame pensar» dan tiempo; no llenes cada pausa con una muletilla. Si falta una palabra, describe su función, categoría o ejemplo. Pide una reformulación concreta, no solo que repitan más fuerte. Después devuelve la conversación con una pregunta.',['No me sale la palabra; es el aparato que sirve para…','¿Quieres decir que tenemos que cambiar la fecha?','¿Puedes decirlo de otra manera?','Lo que intento explicar es…'])],
chunks:['déjame pensar','no me sale la palabra','¿quieres decir que…?','lo que intento explicar es'],
quiz:[q('Para comprobar una interpretación, di…','¿Quieres decir que salimos mañana?',['Sí, siempre.','No sé nada.'],'La pregunta comprueba el contenido específico.'),q('¿Qué objetivo de pronunciación es útil?','Que el mensaje se entienda con claridad.',['Eliminar toda señal de acento extranjero.','Hablar lo más rápido posible.'],'La comprensibilidad sirve al objetivo de comunicación.'),q('En español general, b y v…','No se distinguen como dos fonemas diferentes.',['Siempre suenan como en inglés.','Nunca se pronuncian.'],'La ortografía diferencia letras; la pronunciación habitual no opone b y v.'),q('La palabra día lleva tilde porque…','La vocal cerrada tónica forma hiato.',['Todas las palabras cortas llevan tilde.','Termina en a y es aguda.'],'Dí-a rompe el diptongo esperado.'),q('Si no recuerdas «sacacorchos», puedes decir…','La herramienta que sirve para abrir una botella de vino.',['La cosa, la cosa, la cosa.','No puedo hablar español.'],'Categoría y función permiten seguir comunicando.'),q('El seseo…','Es una pronunciación válida en muchas variedades.',['Es siempre un error.','Solo aparece en inglés.'],'La variación regional no es un defecto de competencia.')],
speak:'Habla dos minutos sobre una actividad que disfrutas. Prohíbete tres palabras habituales y sustitúyelas por explicaciones. Pide después a tu compañero que cambie una pregunta de forma para comprobar comprensión.',write:'Escribe ocho frases que podrías usar para pedir ayuda, mantener un turno y comprobar lo que otra persona ha dicho. Elige tres y utilízalas hoy.',model:'Déjame pensar un momento. No me sale la palabra, pero es una actividad que hacemos al aire libre. Lo que intento decir es que prefiero moverme a quedarme en casa. ¿Quieres decir que este fin de semana no puedes venir? Si te he entendido bien, buscamos otra fecha. ¿Qué día te vendría mejor?'},
];

lessons.push(
{id:'b2-subjuntivo',level:'B2',title:'Elegir indicativo o subjuntivo',tag:'Intención y perspectiva',minutes:45,
goal:'Expresar deseos, valoraciones y dudas sin convertir el subjuntivo en una lista de palabras mágicas.',help:'The subjunctive does not simply mean unreal. It presents content as desired, evaluated, questioned or otherwise dependent on a main expression.',
sections:[
s('Qué hace el subjuntivo','El indicativo suele presentar el contenido como una afirmación del hablante: creo que viene. El subjuntivo aparece en muchos contenidos subordinados a deseos, influencia, valoración, duda o negación de una creencia: quiero que venga; me alegra que estés aquí; no creo que venga. Un hecho puede ser real y llevar subjuntivo: me alegra que hayas venido. La regla «subjuntivo = irreal» no explica estos casos.',['Creo que tienes razón / No creo que tengas razón.','Me alegra que estés aquí.','Es importante que practiques.']),
s('Formas y cambio de sujeto','Presente: hable, hables, hable, hablemos, habléis, hablen; coma/comas; viva/vivas. Muchas formas parten del yo del presente: tengo → tenga, conozco → conozca. Aprende sea, vaya, haya, esté, dé y sepa. Con querer, cuando el sujeto es el mismo suele usarse infinitivo: quiero viajar; si cambia, quiero que viajes. No conviertas toda combinación de dos verbos en que + subjuntivo.',['Espero llegar pronto / Espero que llegues pronto.','Prefiero estudiar por la mañana.','Te recomiendo que lo leas.']),
s('Negación matices y revisión','«No creo que venga» presenta el contenido como no afirmado; «creo que no viene» afirma la ausencia. No todos los verbos con negación exigen siempre subjuntivo: decide qué se afirma y cómo se organiza la frase. Para empezar, domina patrones productivos y luego contrástalos con contextos. Antes de conjugar, identifica sujeto, intención y tiempo de referencia.',['No pienso que sea una buena idea.','Pienso que no es una buena idea.','Puede que tengamos que cambiar la fecha.'])],
chunks:['me alegra que','no creo que','te recomiendo que','puede que'],
quiz:[q('Quiero que tú ___ conmigo.','vengas',['vienes','venir'],'Un deseo dirigido a otro sujeto introduce subjuntivo.'),q('Me alegra que ___ aquí ahora.','estés',['eres','estar'],'Una valoración puede llevar subjuntivo aunque el hecho sea real.'),q('Creo que Ana ___ razón.','tiene',['tenga','tener'],'El hablante afirma su creencia con indicativo.'),q('No creo que Ana ___ razón.','tenga',['tiene siempre','tener'],'La creencia negada presenta el contenido como no afirmado.'),q('Quiero ___ mañana; hablo de mí misma.','viajar',['que viaje yo siempre','viaje'],'Con el mismo sujeto, querer + infinitivo es el patrón natural.'),q('El subjuntivo de conocer en yo es…','conozca',['conoce','conozco'],'La base conozc- conserva la irregularidad del presente.')],
speak:'Recomienda a una amiga cómo adaptarse a vivir en España. Incluye tres consejos, un deseo y una valoración sobre algo que ya ha conseguido.',write:'Escribe un mensaje de 150–180 palabras dando apoyo a alguien que empieza un trabajo. Combina afirmaciones, dudas y recomendaciones sin repetir siempre la misma estructura.',model:'Creo que tienes experiencia suficiente para el puesto. Es normal que al principio necesites ayuda. Te recomiendo que preguntes cuando algo no esté claro y que apuntes los procedimientos nuevos. Me alegra que hayas encontrado un equipo que te apoya. No creo que tengas que hacerlo todo perfectamente desde el primer día.'},
{id:'b2-relativas',level:'B2',title:'Lo conocido lo buscado y lo pendiente',tag:'Relativas y tiempo',minutes:45,
goal:'Distinguir referentes identificados y situaciones pendientes al usar subordinadas.',help:'Busco a alguien que habla… identifies someone; busco a alguien que hable… describes a desired person. Future time clauses normally use subjunctive after cuando.',
sections:[
s('Relativas con indicativo o subjuntivo','«Tengo una amiga que habla japonés» describe una persona identificada. «Busco una amiga que hable japonés» caracteriza a una persona deseada, sin afirmar que exista o que se haya identificado. «No conozco a nadie que lo sepa» niega un referente con esa propiedad. La elección depende de cómo presentas el referente, no solo del verbo buscar.',['Busco el libro que me recomendaste: está identificado.','Busco un libro que me ayude a entender el tema: describo una necesidad.','No hay nadie que pueda venir.']),
s('Cuando hasta que y en cuanto','Para una costumbre o hecho situado, utiliza indicativo: cuando llego, descanso; cuando llegué, descansé. Para un acontecimiento futuro pendiente, subjuntivo: cuando llegue, te llamo; esperaré hasta que termines. Antes de que suele llevar subjuntivo. Después de + infinitivo sirve cuando el sujeto se mantiene: después de cenar, salimos. Evita «cuando llegaré» en este patrón temporal.',['En cuanto tenga noticias, te escribiré.','Cuando tenía tiempo, leía.','Hazlo antes de que se te olvide.']),
s('Finalidad y concesión','Para + infinitivo suele compartir sujeto; para que + subjuntivo introduce una finalidad con otro sujeto. Aunque admite indicativo al afirmar un hecho y subjuntivo para presentarlo como eventual o como información que no se afirma en ese momento. «Aunque llueve, salgo» afirma lluvia; «aunque llueva, saldré» mantiene el plan ante esa posibilidad. El subjuntivo también puede retomar un hecho conocido como irrelevante para la conclusión.',['Te lo explico para que puedas hacerlo sola.','Aunque sea difícil, quiero intentarlo.','Aunque está lejos, vamos a ir.'])],
chunks:['en cuanto tenga','hasta que termine','para que puedas','aunque sea'],
quiz:[q('Te llamaré cuando ___ a casa.','llegue',['llegaré','llego ayer'],'La llegada futura pendiente va en subjuntivo.'),q('Tengo una vecina que ___ francés; la conozco bien.','habla',['hable','hablar'],'El referente se presenta como identificado.'),q('Busco un piso que ___ balcón; aún no he elegido ninguno.','tenga',['tiene seguro','tendrá ayer'],'Se describe una propiedad deseada de un referente no identificado.'),q('Te envío la dirección para que ___ llegar.','puedas',['puedes','poder'],'Para que introduce finalidad con subjuntivo.'),q('Cuando era pequeña, ___ a casa de mi abuela.','iba',['vaya','iré'],'Una costumbre pasada utiliza indicativo.'),q('Aunque llueva, saldremos significa…','El plan se mantiene ante la posibilidad de lluvia.',['El hablante afirma que ya llueve.','El plan siempre se cancela.'],'La lluvia no se afirma como hecho actual en este contexto.')],
speak:'Describe el piso ideal que estás buscando y compáralo con uno que conoces. Después explica qué harás cuando encuentres uno, incluso si no cumple todas tus preferencias.',write:'Escribe 170 palabras sobre un plan aún pendiente. Utiliza dos relativas con distinto modo, tres subordinadas temporales y una concesión.',model:'Busco un piso que tenga luz y que esté cerca del transporte. El que vimos ayer tiene una cocina grande, pero está lejos del trabajo. Cuando encuentre una opción adecuada, pediré una segunda visita. Antes de que firmemos, revisaré el contrato. Aunque no tenga terraza, lo consideraré si la distribución nos permite trabajar cómodamente.'},
{id:'b2-hipotesis',level:'B2',title:'Imaginar alternativas y expresar arrepentimiento',tag:'Condiciones y subjuntivo pasado',minutes:50,
goal:'Diferenciar condiciones abiertas, hipotéticas y contrarias a un pasado ya sucedido.',help:'Si tuviera…, haría… imagines a different present or future. Si hubiera tenido…, habría hecho… imagines a different past.',
sections:[
s('Tres relaciones básicas','Condición abierta: si tengo tiempo, voy/iré. Hipótesis menos cercana o contraria al presente: si tuviera tiempo, iría. Pasado contrafactual: si hubiera tenido tiempo, habría ido. No uses el condicional directamente después de si en estos patrones ordinarios. Hay otras construcciones legítimas con si, como preguntas indirectas, que no siguen este esquema; evita extender la prohibición a todo contexto.',['Si practico, ganaré confianza.','Si viviera más cerca, iría andando.','Si hubiera salido antes, habría llegado a tiempo.']),
s('Formas del imperfecto de subjuntivo','Parte de la tercera persona plural del indefinido, elimina -ron y añade -ra/-ras/-ra/-ramos/-rais/-ran: tuvieron → tuviera; hicieron → hiciera; fueron → fuera. La alternativa en -se suele funcionar en los mismos contextos: tuviese, hiciese, fuese. La primera persona plural lleva tilde: tuviéramos. El pluscuamperfecto de subjuntivo combina hubiera/hubiese + participio.',['Quería que vinieras.','Me gustaría que habláramos de esto.','Ojalá hubiera pedido ayuda antes.']),
s('Deseos y condiciones mixtas','Ojalá tenga tiempo sitúa un deseo posible; ojalá tuviera más tiempo presenta un deseo más distante; ojalá hubiera tenido tiempo mira al pasado. Las condiciones mixtas combinan un pasado alternativo con una consecuencia actual: si hubiera dormido más, ahora estaría menos cansada. Para el resultado contrafactual pasado se usa habría y también hubiera en ciertos contextos; practica primero habría para mantener visible la relación.',['Si hubiera estudiado allí, ahora conocería más gente.','Ojalá pudiera explicarlo mejor.','Me habría gustado quedarme un día más.'])],
chunks:['si tuviera','me habría gustado','ojalá pudiera','si lo hubiera sabido'],
quiz:[q('Si tuviera más tiempo, ___ más.','practicaría',['practicaré seguro','practico ayer'],'La hipótesis con imperfecto de subjuntivo admite condicional en el resultado.'),q('Si hubiera reservado, ___ una mesa.','habría conseguido',['consigo','conseguiré'],'Resultado alternativo de un pasado contrafactual.'),q('El imperfecto de subjuntivo de tener es…','tuviera',['teniera','tendría'],'Tuvieron aporta la base tuvie-.'),q('Me gustaría que ___ juntas; nosotras.','practicáramos',['practicamos','practicaríamos que'],'La expresión de deseo introduce subjuntivo y la forma lleva tilde.'),q('Si hubiera dormido más, ahora ___ menos cansada.','estaría',['estuve','había'],'Es una condición mixta: causa pasada y resultado presente.'),q('Ojalá ___ pedido ayuda ayer.','hubiera',['haya mañana','habré'],'El deseo sobre un pasado ya sucedido utiliza pluscuamperfecto de subjuntivo.')],
speak:'Imagina cómo cambiaría tu vida si pudieras trabajar desde cualquier lugar. Después cuenta una decisión pasada y qué habría ocurrido con otra elección.',write:'Escribe 180 palabras sobre una oportunidad perdida y lo que has aprendido. Incluye condición presente, contrafactual pasada y una condición mixta.',model:'Si pudiera organizar mi horario libremente, dedicaría más tiempo a conversar. El año pasado tuve la oportunidad de apuntarme a un curso, pero la dejé pasar. Si hubiera hablado con la profesora, habría encontrado un grupo adecuado. Si hubiera empezado entonces, ahora tendría más práctica. Aun así, puedo aprovechar lo que he aprendido por mi cuenta.'},
{id:'b2-instrucciones',level:'B2',title:'Dar instrucciones y explicar qué ocurrió',tag:'Imperativo se y pasiva',minutes:45,
goal:'Dar instrucciones claras y elegir cómo presentar al agente de una acción.',help:'Spanish se can mark reflexive action, an impersonal statement, a passive construction or an affected person in an accidental event. Identify the full pattern.',
sections:[
s('Imperativo y pronombres','Tú afirmativo: habla, come, vive; irregularidades frecuentes: di, haz, ve, pon, sal, sé, ten, ven. Tú negativo usa subjuntivo: no hables, no lo hagas. Usted y ustedes usan formas de subjuntivo en ambas polaridades: lea/no lea. Vosotros afirmativo cambia -r por -d: hablad; negativo: no habléis. Los pronombres se unen al afirmativo y van delante del negativo.',['Dímelo / No me lo digas.','Haga clic aquí / No cierre la ventana.','Id con cuidado; no os alejéis.']),
s('Pasiva e impersonal','La pasiva con ser + participio enfoca lo que recibe la acción: la propuesta fue aprobada. El participio concuerda. La pasiva refleja suele ser natural en avisos: se venden entradas; el verbo concuerda con entradas. La impersonal con se no tiene sujeto léxico y usa singular: se vive bien aquí; se entrevistó a tres candidatas. La a personal ayuda a reconocer este último patrón.',['Se alquilan habitaciones.','Se busca a los responsables.','La decisión fue anunciada ayer.']),
s('Accidentes y responsabilidad','«Se me cayó el vaso» combina se con un pronombre que indica la persona afectada; el verbo concuerda con lo caído. No elimina automáticamente responsabilidad, pero presenta el hecho como algo que ocurrió. Contrasta «rompí el vaso» con «se me rompió el vaso». Estar + participio presenta un estado resultante: la puerta está cerrada; ser + participio presenta una acción pasiva.',['Se me olvidaron las llaves.','Se nos ha estropeado el coche.','La puerta fue cerrada a las ocho y ahora está cerrada.'])],
chunks:['se me ha olvidado','se necesita','no te preocupes','hazlo con calma'],
quiz:[q('El imperativo negativo de «dímelo» es…','No me lo digas.',['No dímelo.','No me lo dices tú.'],'El negativo usa subjuntivo y pronombres delante.'),q('En un anuncio: se ___ habitaciones.','alquilan',['alquila siempre','alquilar'],'Pasiva refleja con sujeto plural habitaciones.'),q('Se ___ a tres candidatas ayer.','entrevistó',['entrevistaron siempre','entrevistan mañana'],'La a personal y el patrón impersonal mantienen el verbo en singular.'),q('Se me ___ las llaves en casa.','olvidaron',['olvidó','olvidé las'],'El sujeto las llaves exige plural.'),q('La propuesta fue ___ por el equipo.','aprobada',['aprobado','aprobar'],'El participio pasivo concuerda con propuesta.'),q('«La puerta está cerrada» presenta…','Un estado resultante.',['Necesariamente quién la cerró.','Siempre una acción futura.'],'Estar + participio describe el estado.')],
speak:'Explica a una visita cómo llegar, entrar y utilizar tres cosas de tu casa. Introduce después un pequeño accidente y explica cómo solucionarlo.',write:'Escribe instrucciones de 160 palabras para organizar una actividad. Incluye imperativos afirmativos y negativos, un aviso con pasiva refleja y una explicación de un imprevisto.',model:'Llegad diez minutos antes y esperad en la entrada. No dejéis las mochilas en el pasillo. Se entregarán los materiales al comenzar la actividad. Si se os pierde una pieza, avisad a la persona responsable. La sala está preparada, pero las ventanas deben permanecer cerradas durante la grabación.'},
{id:'b2-discurso',level:'B2',title:'Transmitir lo que otra persona dijo',tag:'Estilo indirecto',minutes:45,
goal:'Contar mensajes, preguntas y peticiones manteniendo referencias temporales claras.',help:'Reported speech changes depend on the new viewpoint. Do not mechanically shift every tense if the information still applies.',
sections:[
s('Afirmaciones y cambio de perspectiva','Con un verbo introductor en presente puedes mantener el tiempo: dice que vive aquí. Con dijo, un presente del mensaje puede pasar a imperfecto: dijo que vivía allí. Un futuro puede pasar a condicional: dijo que vendría. Un pasado anterior suele expresarse con pluscuamperfecto. Cambia también yo/tú, aquí/allí y mañana/al día siguiente cuando el nuevo contexto lo requiera. No es un algoritmo obligatorio: «dijo que vive aquí» puede mantener una información vigente.',['«Estoy cansada» → Dijo que estaba cansada.','«Vendré mañana» → Dijo que vendría al día siguiente.','Me dijo que trabaja aquí; todavía es su empleo.']),
s('Preguntas indirectas','Las preguntas de sí/no se introducen con si: preguntó si podía venir. Las preguntas con interrogativo conservan qué, quién, dónde, cuándo, cómo y por qué, con tilde: preguntó dónde vivía. No conservan necesariamente la entonación interrogativa ni los signos si la frase completa es afirmativa. Distingue por qué, pregunta por causa, y porque, explicación.',['Me preguntó si quería ir.','No sé cuándo empieza.','Quiero saber por qué cambió el plan.']),
s('Peticiones e intención del hablante','Para transmitir una orden o petición, usa pidió que + subjuntivo: me pidió que esperara. Verbos como prometió, advirtió, explicó, propuso y negó describen la intención y permiten evitar una repetición constante de dijo. No atribuyas certeza adicional: «sugirió» no significa «demostró». Cuando resumas, conserva también reservas y condiciones.',['Me pidió que le enviara el documento.','Propuso salir antes, pero advirtió que quizá llovería.','Negó haber recibido el mensaje.'])],
chunks:['me preguntó si','me pidió que','según me explicó','advirtió que'],
quiz:[q('«¿Quieres venir?» → Me preguntó ___ quería venir.','si',['que','porque'],'Una pregunta de sí/no se introduce con si.'),q('«Envíame el archivo» → Me pidió que se lo ___.','enviara',['envié','enviaré'],'Una petición indirecta en pasado introduce imperfecto de subjuntivo.'),q('«Vendré mañana», contado días después: dijo que…','vendría al día siguiente.',['vendrá ayer.','viene mañana siempre.'],'Se ajustan tiempo y marcador a la nueva perspectiva.'),q('Elige la grafía correcta.','No sé por qué se fue.',['No sé porque se fue.','No sé porqué se fue.'],'Por qué introduce una interrogativa indirecta de causa.'),q('«Sugirió una solución» significa que…','La propuso para considerarla.',['Probó que era la única solución.','Ordenó aplicarla sin discusión.'],'El verbo de comunicación importa para representar la intención.'),q('¿Es siempre obligatorio cambiar presente a imperfecto?','No, puede mantenerse información vigente.',['Sí, sin excepción.','No existe el estilo indirecto.'],'El tiempo depende de la perspectiva y vigencia del contenido.')],
speak:'Escucha un mensaje de tu compañero y transmítelo a una tercera persona imaginaria. Conserva fecha, lugar, petición y una incertidumbre.',write:'Escribe un resumen de 180 palabras de una conversación sobre un cambio de planes. Diferencia lo confirmado, lo propuesto y lo pendiente.',model:'Ana explicó que el restaurante estaba completo. Propuso cenar en otro sitio y me preguntó si podía llegar antes. Le dije que saldría del trabajo a las seis. Me pidió que avisara a Marta, pero advirtió que la nueva reserva todavía no estaba confirmada. Según me explicó, tendría una respuesta por la tarde.'},
{id:'b2-argumentar',level:'B2',title:'Defender una opinión con matices',tag:'Cohesión y argumentación',minutes:45,
goal:'Sostener una opinión con razones, ejemplos y respuesta a una objeción.',help:'Build a claim, a reason, an example and a qualification. More connectors do not automatically make an argument stronger.',
sections:[
s('Una estructura que se puede decir','Empieza con una postura limitada: me parece una buena opción para… Añade una razón, un ejemplo concreto y una reserva. Cierra con una propuesta. No confundas opinión y dato; «en mi experiencia» limita una generalización. Hablar con soltura incluye responder a la idea del otro, no recitar un texto preparado.',['En mi experiencia, vivir cerca del trabajo reduce mucho el estrés.','Por ejemplo, antes perdía una hora en el autobús.','Eso sí, puede resultar más caro.']),
s('Conectores con una función','Porque introduce causa; por eso y así que, consecuencia; sin embargo, contraste; además, adición; de hecho, confirmación o refuerzo; es decir, reformulación; en cambio, contraste entre elementos. Aunque subordina una concesión. Evita combinar conectores incompatibles o llenar cada frase con uno. En escritura, sin embargo suele separarse por comas.',['Es caro; sin embargo, ofrece más flexibilidad.','No hay tren, así que iremos en autobús.','No rechazo el plan; es decir, quiero ajustarlo.']),
s('Desacuerdo y precisión','Puedes conceder una parte antes de plantear una objeción: entiendo tu punto, pero… Distingue todos, la mayoría, algunos y en ciertos casos. «No siempre» no significa «nunca». Si el otro presenta una excepción, revisa el alcance de tu postura en lugar de repetirla más fuerte. Una conclusión útil puede ser provisional.',['Estoy de acuerdo en parte.','No diría que ocurra siempre.','Quizá podamos encontrar una opción intermedia.'])],
chunks:['desde mi punto de vista','entiendo tu punto','eso sí','una opción intermedia'],
quiz:[q('Presenta viajar en autobús como consecuencia de no haber tren: No hay tren, ___ iremos en autobús.','así que',['aunque','a pesar de'],'El segundo segmento expresa consecuencia.'),q('Un marcador de reformulación es…','es decir',['por tanto','en cambio'],'Es decir vuelve a expresar una idea.'),q('En este ejemplo funciona unas veces y otras falla. «No siempre funciona» significa aquí…','Funciona en algunos casos, pero no en todos.',['Nunca funciona.','Siempre funciona.'],'En el contexto dado hay aciertos y fallos. No siempre niega que funcione en todos los casos; por sí solo no permite calcular con qué frecuencia funciona.'),q('Para un contraste entre dos opciones usa…','en cambio',['porque','para que'],'En cambio contrapone elementos.'),q('Una buena respuesta a una objeción es…','Reconocer la parte válida y ajustar tu postura.',['Repetir exactamente la opinión inicial.','Cambiar de tema sin responder.'],'La interacción requiere incorporar información del interlocutor.'),q('Un ejemplo personal demuestra por sí solo…','Lo ocurrido en ese caso, no una regla universal.',['Que todas las personas viven igual.','Que no hace falta justificar nada.'],'El alcance de la evidencia debe corresponder al de la afirmación.')],
speak:'Defiende si prefieres vivir en el centro o fuera de la ciudad. Tu compañero plantea una objeción económica y otra social. Responde y negocia una conclusión.',write:'Escribe 180–220 palabras sobre trabajar desde casa. Incluye postura, dos razones, un ejemplo, una objeción y una conclusión limitada.',model:'Trabajar desde casa puede mejorar la organización del día, sobre todo cuando los desplazamientos son largos. Por ejemplo, permite dedicar ese tiempo al descanso. Sin embargo, no todas las viviendas ofrecen un espacio adecuado. Entiendo que algunas personas prefieran la oficina por el contacto social. Por eso, me parece razonable ofrecer una opción flexible cuando el trabajo lo permita.'},
{id:'b2-lexico',level:'B2',title:'Encontrar palabras y combinaciones naturales',tag:'Léxico e interferencias del inglés',minutes:40,
goal:'Recuperar vocabulario en bloques, evitar falsos amigos y escribir con más precisión.',help:'Learn chunks such as tomar una decisión and darse cuenta de. Actual means current; actualmente means currently. False friends depend on context, so check the complete sentence.',
sections:[
s('Colocaciones que se recuperan juntas','En lugar de memorizar decisión, aprende tomar una decisión; en lugar de cuenta, darse cuenta de. Otros bloques son prestar atención, tener en cuenta, cumplir un plazo, plantear un problema, resolver una duda, cometer un error y sacar una conclusión. Construye tarjetas con un hueco y una experiencia tuya. Recupera primero sin mirar, luego comprueba. Revisa al día siguiente, a los pocos días y la semana siguiente como pauta flexible.',['Me di cuenta de que no había entendido la pregunta.','Tenemos que tener en cuenta el presupuesto.','No he conseguido cumplir el plazo.']),
s('Transferencias que merecen atención','Actualmente suele significar currently, y actual, current. Para actually muchas veces necesitas en realidad. Asistir a una reunión no equivale a ayudar; atender a alguien puede tener otros sentidos. Sensible suele referirse a sensibilidad, sensato a buen juicio. Embarazada no significa embarrassed: según el caso, avergonzada o me da vergüenza. También evita «aplicar para un trabajo» como traducción automática; en España son habituales solicitar un puesto o presentarse a una oferta.',['Actualmente vivo en España; en realidad, crecí en Florida.','Me da vergüenza equivocarme, pero sigo hablando.','Solicité el puesto y asistí a la entrevista.']),
s('Acentos y palabras que conectan','Distingue si condicional y sí afirmativo; tu posesivo y tú pronombre; el artículo y él pronombre; de preposición y dé del verbo dar. Qué/cómo/cuándo llevan tilde en preguntas directas e indirectas. Porque da una causa, por qué pregunta, el porqué nombra la razón y por que aparece en otras construcciones. Si dudas, reformula y consulta una fuente lingüística: no bases la decisión en una regla inglesa.',['Si vienes, sí que podemos hablar.','No sé cómo hacerlo.','Espero que me dé una respuesta.'])],
chunks:['tomar una decisión','darse cuenta de','tener en cuenta','en realidad'],
quiz:[q('La combinación natural es…','tomar una decisión',['hacer una decisión','poner una decisión'],'Tomar una decisión es una colocación habitual.'),q('Para expresar actually en «Actually, I grew up in Florida» usa…','En realidad',['Actualmente','Actual'],'Actualmente se refiere al momento presente.'),q('Embarrassed puede expresarse como…','avergonzada',['embarazada','asistida'],'Embarazada se refiere a un embarazo.'),q('Elige la frase correcta.','Espero que me dé una respuesta.',['Espero que me de una respuesta.','Espero que mí de una respuesta.'],'Dé lleva tilde diacrítica cuando es forma verbal.'),q('Elige la frase correcta.','No sé cómo explicarlo.',['No sé como explicarlo.','No se cómo explicarlo.'],'Sé es forma de saber y cómo introduce una interrogativa indirecta.'),q('«Asistí a la reunión» significa…','Estuve presente en la reunión.',['Ayudé necesariamente a todo el mundo.','Cancelé la reunión.'],'Asistir a señala participación o presencia.')],
speak:'Explica una decisión reciente usando tomar una decisión, tener en cuenta, darse cuenta y en realidad. Si falta una palabra, parafrasea y vuelve a la idea principal.',write:'Escribe 180 palabras sobre una dificultad de adaptación. Revisa después tildes diacríticas, interrogativos y cinco combinaciones de palabras.',model:'Actualmente me siento más cómoda hablando español. En realidad, lo que más me cuesta es participar cuando varias personas hablan a la vez. Me he dado cuenta de que necesito pedir aclaraciones más concretas. Antes de tomar una decisión sobre cómo estudiar, quiero tener en cuenta mi horario y los temas que me interesan.'},
{id:'b2-comprender',level:'B2',title:'Entender discursos más largos',tag:'Escucha lectura y síntesis',minutes:45,
goal:'Separar idea principal, detalles, postura y evidencia en un texto o audio.',help:'First identify the purpose and overall message. Then look for evidence for each answer. Recognizing the same word in an option is not enough.',
sections:[
s('Primera pasada y segunda pasada','En la primera lectura o escucha, identifica tema, quién habla, a quién y con qué propósito. En la segunda, localiza causas, contrastes, fechas y conclusiones. No traduzcas cada palabra antes de seguir. Si una frase se pierde, recupera el hilo con el siguiente marcador. Al leer, adapta velocidad: busca un dato rápido o relee una relación compleja.',['Tema: vivienda. Propósito: comparar soluciones.','Idea principal: el precio no es el único criterio.','Detalle: el segundo piso tiene menos luz.']),
s('Opciones y distractores','Una respuesta puede repetir palabras del texto y aun así cambiar quién actúa, cuándo, la causa o el grado de certeza. Busca evidencia concreta, no familiaridad. «Podría mejorar» no equivale a «mejoró»; «algunas» no equivale a «todas». Para inferir una palabra, combina contexto, prefijos y relación con la frase; comprueba después si la interpretación encaja.',['El autor dice que podría funcionar, no que esté demostrado.','La primera propuesta fue descartada, no elegida.','Sin embargo anuncia un giro que puede cambiar la interpretación.']),
s('De comprender a hablar','Resume sin mirar en tres frases: idea central, razón principal y límite o consecuencia. Luego añade tu opinión en una frase aparte. No atribuyas al autor tu interpretación personal. Para entrenar escucha natural usa distintas voces y variedades, y vuelve a una transcripción solo después de intentar comprender. La voz sintética de esta web sirve como apoyo; no sustituye los audios reales.',['La autora sostiene que…','Su principal argumento es…','Aclara, sin embargo, que…','Por mi parte, considero que…'])],
chunks:['la idea principal es','el autor sostiene','no se puede concluir que','por mi parte'],
quiz:[q('«La medida podría reducir el tráfico» expresa…','Una posibilidad.',['Un resultado ya comprobado.','Una obligación legal.'],'Podría no afirma que el efecto haya ocurrido.'),q('Si una opción repite palabras del audio…','Todavía necesitas comprobar el sentido completo.',['Siempre es la correcta.','Siempre es falsa.'],'Las coincidencias léxicas pueden aparecer en distractores.'),q('Un resumen fiel debe…','Separar la postura de la fuente y tu opinión.',['Añadir datos que no se mencionan.','Copiar cada frase.'],'La fidelidad requiere conservar atribución y alcance.'),q('En la primera escucha conviene buscar…','Tema y propósito general.',['La traducción de todas las palabras.','Solo el último número.'],'La visión global orienta la escucha posterior.'),q('«Algunas vecinas se opusieron» permite afirmar…','Que hubo oposición de una parte de las vecinas.',['Que todas se opusieron.','Que ninguna se opuso.'],'Algunas indica una parte del grupo y no autoriza a afirmar que todas se opusieron.'),q('Para comprobar escucha real, usa…','Audios humanos y distintas variedades.',['Solo una voz sintética lenta.','Siempre el texto visible antes de escuchar.'],'La variación y el habla natural forman parte de la comprensión.')],
speak:'Escucha un audio de la biblioteca, resume su postura y sus reservas y plantea una pregunta crítica. Tu compañero compara el resumen con la fuente.',write:'Resume un artículo de 300–500 palabras en 100–120 palabras; después escribe tu opinión en un párrafo separado de 80 palabras. Marca qué afirmaciones pertenecen a la fuente.',model:'El texto plantea que ampliar las zonas peatonales puede mejorar la vida del barrio. Su argumento principal es que permite utilizar el espacio para actividades cotidianas. Sin embargo, señala que el reparto de mercancías necesita una solución específica. Por mi parte, apoyaría una prueba temporal antes de aplicar el cambio de manera permanente.'}
);

lessons.push(
{id:'c1-matices',level:'C1',title:'Cambiar de perspectiva con el modo verbal',tag:'Subjuntivo avanzado',minutes:50,
goal:'Interpretar cambios de modo como cambios de compromiso, referencia y perspectiva.',help:'Advanced mode choice is a matter of viewpoint and discourse, not just a longer list of subjunctive triggers.',
sections:[
s('Afirmar o poner información en segundo plano','Elige el modo según qué contenido presentas como afirmación propia. «Aunque tiene experiencia, necesita apoyo» afirma su experiencia; «aunque tenga experiencia, necesita apoyo» puede admitirla o tratarla como una condición irrelevante para la conclusión. No deduzcas automáticamente que el subjuntivo señala un hecho falso. En respuestas breves, el contexto puede convertir en conocida una información que no se vuelve a afirmar.',['Aunque lo sepas, conviene repasarlo.','Por mucho que insistas, no cambiará la fecha.','No porque sea fácil, sino porque merece la pena.']),
s('Referentes y consecuencias de la elección','«Quien termine primero puede salir» permite un referente no identificado; «quien terminó primero salió» remite a un hecho situado. Distingue cualquier persona que cumpla una condición de una persona concreta. En comparaciones con como si se usan imperfecto o pluscuamperfecto de subjuntivo: habla como si lo supiera; actuó como si no hubiera pasado nada.',['Quien tenga dudas puede preguntar.','Lo explicó como si hubiera estado allí.','Busco a la persona que envió el mensaje.']),
s('Tiempo subordinado y revisión','Alinea la subordinada con el momento del deseo, valoración o creencia. «Me alegra que hayas venido» mira una llegada anterior al presente; «me alegró que hubieras venido» la sitúa antes de una valoración pasada. En otros contextos puede aparecer vinieras al presentar el hecho pasado sin enfatizar anterioridad. Explica primero la línea temporal y después elige la forma; hay variación legítima que una regla mecánica no recoge.',['Me sorprende que no lo sepa.','Me sorprendió que no lo supiera.','Me alegra que hayas encontrado una solución.'])],
chunks:['por mucho que','como si','quien tenga','no porque… sino porque'],
quiz:[q('Habla como si ___ la respuesta; pero no la conoce.','supiera',['sabe','sabrá'],'Como si introduce una comparación hipotética con imperfecto de subjuntivo.'),q('Quien ___ dudas puede preguntar; no se identifica a nadie.','tenga',['tuvo','tendría'],'La relativa libre caracteriza posibles participantes.'),q('Me alegra que ___ venido hoy.','hayas',['habrás','has siempre'],'Una llegada anterior valorada ahora puede usar perfecto de subjuntivo.'),q('Actuó como si no ___ pasado nada antes.','hubiera',['habrá','ha'],'Como si + pluscuamperfecto plantea una anterioridad hipotética.'),q('«Aunque tenga experiencia» demuestra por sí solo que no tiene experiencia.','No; no afirma necesariamente que sea falso.',['Sí, siempre.','Solo si está en presente.'],'El subjuntivo puede admitir un hecho sin afirmarlo como información principal.'),q('Por mucho que ___, no cambiaré de opinión.','insistas',['insistirás','insistes siempre'],'La concesiva intensiva presenta la insistencia como insuficiente para cambiar el resultado.')],
speak:'Defiende una decisión que mantendrías aunque cambiaran tres circunstancias. Tu compañero propone hechos conocidos y posibilidades; adapta los modos y explica la diferencia.',write:'Escribe 220 palabras sobre una decisión controvertida. Incluye concesión de un hecho conocido, hipótesis, comparación con como si y una valoración de un hecho anterior.',model:'Aunque la propuesta tenga ventajas, no basta con anunciarla para que funcione. Me sorprende que se haya presentado como una solución definitiva. Quien conozca la situación del barrio sabe que existen necesidades distintas. Por mucho que se simplifique el mensaje, habrá que escuchar a las personas afectadas. No deberíamos actuar como si ya hubiéramos resuelto todas las dificultades.'},
{id:'c1-aspecto',level:'C1',title:'Afinar certeza duración y cambio',tag:'Modalidad y perífrasis',minutes:45,
goal:'Distinguir inferencia, obligación, evolución y culminación con recursos verbales.',help:'Debe de estar… suggests an inference; tiene que estar… can express either obligation or a strong inference depending on context. Meaning comes from the complete situation.',
sections:[
s('Grados de certeza y fuente','Es posible que, probablemente, al parecer, según y todo apunta a que no expresan el mismo compromiso. Al parecer suele indicar información indirecta; según atribuye una fuente. Futuro de conjetura: tendrá unos cuarenta años; condicional de conjetura pasada: serían las diez. No conviertas una estimación en una cifra exacta. Diferencia tengo que terminar, obligación, y tiene que haber una explicación, inferencia según contexto.',['Al parecer, cambiarán el horario.','Serían las diez cuando nos llamaron.','Debe de estar en camino.']),
s('Desarrollo y resultado','Ir + gerundio muestra progresión: voy entendiendo. Venir + gerundio presenta desarrollo desde antes: viene aumentando. Llevar + participio cuantifica resultado acumulado: llevo leídas veinte páginas; el participio concuerda con lo contabilizado. Acabar por + infinitivo presenta un resultado final tras un proceso; dejar de + infinitivo, interrupción. Estar a punto de expresa inminencia.',['Voy ganando confianza poco a poco.','Llevo leídas tres novelas.','Acabamos por cambiar de plan.']),
s('Verbos de cambio','Ponerse suele presentar un cambio de estado: se puso nerviosa. Quedarse puede enfocar un resultado: se quedó sin palabras. Volverse caracteriza cambios, a menudo percibidos como fuertes: se volvió desconfiado. Hacerse y llegar a ser pueden presentar evolución, elección o logro según contexto. No traduzcas cada become con un único verbo; selecciona el tipo de cambio.',['Se puso roja al escuchar el comentario.','Se quedó callada.','Se hizo profesora y llegó a ser directora.'])],
chunks:['al parecer','todo apunta a que','voy entendiendo','acabar por'],
quiz:[q('Llevo ___ veinte páginas.','leídas',['leído','leyendo veinte ya'],'Llevar + participio de resultado concuerda con páginas.'),q('«Serían las diez» puede expresar…','Una estimación sobre una hora pasada.',['Siempre una hora exacta futura.','Una orden.'],'El condicional puede tener valor de conjetura pasada.'),q('Voy entendiendo significa…','Comprendo cada vez más de forma progresiva.',['Voy físicamente a un lugar llamado Entendiendo.','Dejé de comprender.'],'Ir + gerundio presenta progresión.'),q('Se ___ nerviosa al empezar la entrevista.','puso',['hizo de','llegó nervios'],'Ponerse presenta un cambio de estado.'),q('Al parecer introduce a menudo…','Información obtenida indirectamente.',['Una certeza demostrada por el hablante.','Una obligación personal.'],'El marcador reduce el compromiso y señala acceso indirecto.'),q('Después de discutirlo, acabamos ___ elegir la primera opción.','por',['de que','en que'],'Acabar por + infinitivo presenta el desenlace de un proceso.')],
speak:'Cuenta cómo ha cambiado tu manera de aprender y distingue lo observado de lo que supones. Usa dos perífrasis de evolución y dos marcadores de certeza.',write:'Escribe 220 palabras sobre un cambio social cercano. Atribuye fuentes, limita afirmaciones y diferencia evolución y resultado.',model:'En los últimos meses voy entendiendo mejor las conversaciones de grupo. Llevo escuchadas varias entrevistas completas, aunque todavía necesito repetir algunos fragmentos. Al parecer, mi dificultad principal está en reconocer expresiones enlazadas. Antes me ponía nerviosa cuando perdía una frase; ahora intento recuperar el hilo y acabo por entender la idea general.'},
{id:'c1-registro',level:'C1',title:'Elegir el tono y leer entre líneas',tag:'Pragmática y registro',minutes:45,
goal:'Adaptar peticiones, críticas y desacuerdos a la relación y al contexto.',help:'A sentence can be grammatically correct and socially unsuitable. Consider relationship, purpose and setting before choosing its wording.',
sections:[
s('Registro y relación','No necesitas hablar igual con una amiga, una profesora y una persona desconocida. Ajusta tratamiento, grado de explicitud y vocabulario. Tú/usted no equivalen de forma fija a informal/formal en todas las regiones: observa la práctica local y pregunta si dudas. La cortesía puede expresar el motivo de una petición y ofrecer margen real de elección. Evita fórmulas excesivamente solemnes en conversaciones cotidianas.',['¿Me lo pasas cuando puedas?','¿Podría enviarme el documento antes del viernes?','Te quería preguntar una cosa.']),
s('Atenuar sin ocultar el mensaje','Me parece que, quizá convendría y sería útil permiten moderar una crítica. No uses tantos atenuantes que la otra persona no entienda qué necesitas. Distingue crítica de una acción y juicio sobre una persona. Para disentir, reconoce lo entendido y especifica el punto de discrepancia. «Con todo respeto» no garantiza cortesía si después atacas a la persona.',['Entiendo la propuesta, pero me preocupa el plazo.','Quizá convendría revisar esta parte.','Necesito que confirmemos la fecha hoy.']),
s('Implicaturas humor y reparación','«Está un poco lejos» puede ser una descripción o una forma de rechazar un plan. El tono y la situación orientan; no atribuyas intención con certeza a partir de una frase aislada. La ironía puede depender de una contradicción entre palabras y contexto. Si no estás segura, comprueba: «¿Lo dices en serio o es una broma?». Comprender implícitos también incluye reconocer cuándo falta contexto.',['¿Te parece demasiado lejos para ir esta tarde?','Cuando dices que es interesante, ¿lo recomiendas?','Si te he entendido bien, preferirías otra opción.'])],
chunks:['me preocupa que','quizá convendría','si te he entendido bien','¿lo dices en serio?'],
quiz:[q('Para pedir un archivo a alguien desconocido, una opción adecuada es…','¿Podría enviarme el archivo, por favor?',['Pásamelo ya, sin contexto.','No necesito explicarle nada nunca.'],'La forma ofrece un tono cortés acorde con una relación distante.'),q('«Está un poco lejos» significa siempre un rechazo.','No; hacen falta tono y contexto.',['Sí, es una regla gramatical.','Solo si usa subjuntivo.'],'La intención pragmática no se deduce con certeza de palabras aisladas.'),q('Una crítica centrada en la tarea sería…','Esta parte necesita una explicación más clara.',['No sabes hacer nada.','Eres imposible.'],'Se identifica una acción que puede mejorarse.'),q('Para comprobar ironía puedes preguntar…','¿Lo dices en serio o es una broma?',['¿Por qué nunca dices la verdad?','Ya sé exactamente lo que piensas.'],'La pregunta permite aclarar sin atribuir mala intención.'),q('Tú y usted…','Dependen también de la variedad y la relación.',['Tienen idéntico uso social en todos los países.','Nunca se usan en España.'],'El tratamiento presenta variación regional y contextual.'),q('Atenuar una petición debería…','Mantener claro lo que se necesita.',['Eliminar toda petición reconocible.','Añadir siempre cinco disculpas.'],'La cortesía debe convivir con claridad.')],
speak:'Pide el mismo cambio de fecha a una amiga, a una profesora y a un servicio de atención al cliente. Tu compañero indica en cada caso una restricción distinta.',write:'Escribe dos versiones de una reclamación: un mensaje cercano de 100 palabras y un correo formal de 180. Conserva los hechos y cambia tratamiento y tono.',model:'Buenos días: escribo para consultar un cambio en mi reserva. La confirmación recibida indica una fecha distinta de la que solicité. ¿Podrían revisar lo ocurrido y confirmarme si es posible corregirla? Adjunto la referencia para facilitar la consulta. Me gustaría resolverlo antes del viernes, porque necesito organizar el desplazamiento. Muchas gracias por su ayuda.'},
{id:'c1-mediacion',level:'C1',title:'Explicar información para otra persona',tag:'Síntesis y mediación',minutes:50,
goal:'Seleccionar y adaptar información a las necesidades de un destinatario.',help:'Mediation is more than translation or shortening. Identify what the recipient needs and preserve the source’s limits, priorities and uncertainty.',
sections:[
s('Propósito destinatario y selección','Antes de resumir, decide quién recibirá la información y qué debe poder hacer después. Una amiga necesita instrucciones prácticas; un equipo, opciones y consecuencias. Selecciona datos pertinentes, reorganiza y explica términos especializados. Si un dato no está en la fuente, no lo inventes para rellenar un hueco. Puedes señalar lo que falta.',['Para inscribirte necesitas…','La diferencia que te afecta es…','La información no especifica si…']),
s('Fidelidad y reservas','Mantén cifras, fechas, condiciones, atribuciones y grados de certeza. «Recomienda» no equivale a «exige»; «podría» no equivale a «va a». Un resumen demasiado breve puede eliminar una excepción decisiva. Distingue la voz de la fuente y tu recomendación. Si traduces para una persona anglófona, conserva el sentido funcional y no el orden de cada palabra.',['El aviso recomienda reservar; no dice que sea obligatorio.','La tarifa incluye el transporte, pero no la comida.','Según el informe, los resultados son preliminares.']),
s('Proceso de trabajo y comprobación','Anota propósito, tres datos esenciales y una limitación. Redacta sin copiar frases extensas. Comprueba después contra la fuente: ¿he cambiado una cantidad?, ¿he omitido una excepción?, ¿se entiende qué hacer? Para mediación oral, utiliza señalización explícita: primero, lo importante, en tu caso. Termina comprobando comprensión con una pregunta concreta.',['En tu caso, el segundo requisito es el más importante.','¿Queda claro qué documento tienes que llevar?','Mi recomendación es distinta de lo que exige el aviso.'])],
chunks:['en tu caso','lo importante es','la fuente no especifica','según el aviso'],
quiz:[q('Una fuente «recomienda reservar». Un resumen fiel dice…','Se aconseja reservar.',['Es obligatorio reservar.','Está prohibido llegar sin reserva.'],'No se debe convertir consejo en obligación.'),q('La tarifa incluye transporte, no comida. ¿Qué debes conservar?','La inclusión y la exclusión relevantes.',['Solo que todo está incluido.','Una estimación inventada de la comida.'],'La excepción puede ser decisiva para el destinatario.'),q('Antes de mediar conviene identificar…','El destinatario y qué necesita hacer.',['Solo el número de palabras.','La traducción de la primera frase.'],'La selección depende del propósito.'),q('Si la fuente no aclara un dato…','Señala que no se especifica.',['Invéntalo si parece probable.','Preséntalo como confirmado.'],'La fidelidad incluye reconocer información ausente.'),q('Un resultado preliminar…','No debe presentarse como conclusión definitiva.',['Siempre prueba una regla universal.','No puede mencionarse.'],'Hay que mantener el grado de certeza.'),q('Una mediación útil puede…','Reorganizar la información para hacerla comprensible.',['Cambiar fechas para simplificar.','Omitir todas las condiciones.'],'Adaptar estructura no autoriza alterar contenido.')],
speak:'Usa un aviso de la biblioteca y explica a tu compañero qué tiene que hacer para participar. Añade una recomendación propia y sepárala de las condiciones de la fuente.',write:'A partir de dos textos sobre una actividad, redacta una nota de 200 palabras para una persona que no ha leído ninguno. Incluye requisitos, alternativas y una duda pendiente.',model:'Para participar tienes que inscribirte antes del jueves. El aviso recomienda llegar quince minutos antes, pero no indica que sea obligatorio. La entrada incluye los materiales; la comida se paga aparte. En tu caso convendría consultar si hay una opción vegetariana, porque la información no lo especifica. Yo elegiría el turno de mañana para evitar volver demasiado tarde.'},
{id:'c1-implicitos',level:'C1',title:'Escuchar intención reservas y contraste',tag:'Comprensión avanzada',minutes:50,
goal:'Reconocer posturas implícitas sin sobreinterpretar lo que se oye.',help:'Inference needs evidence. Distinguish what is explicitly stated, what is strongly implied and what you merely suspect.',
sections:[
s('Postura y organización','En discursos largos, sigue cómo cambia la postura: una introducción puede presentar una opinión ajena que después se cuestiona. Según algunos no atribuye automáticamente esa creencia a quien habla. Detecta concesiones, reformulaciones, contrastes y conclusiones provisionales. Toma notas de relaciones, no de todas las palabras.',['Se suele decir que…; sin embargo…','No niego su utilidad; cuestiono su aplicación.','Dicho esto, todavía faltan datos.']),
s('Entonación e inferencia','El énfasis, las pausas y el tono pueden orientar una intención. No son una prueba universal de ironía o enfado. Busca coincidencia entre situación, contenido y tono. Una inferencia razonable tiene una pista identificable; una suposición personal puede no tenerla. Aprende a responder «no se puede determinar» cuando la fuente no permite concluir.',['Es barato, eso desde luego; otra cosa es que nos convenga.','Si no cambia nada, seguiremos con el mismo problema.','La persona reconoce una ventaja, pero cuestiona la decisión.']),
s('Entrenar con materiales auténticos','Elige una entrevista o debate breve con transcripción disponible. Primera escucha: tesis y actitud. Segunda: reservas y argumentos. Después consulta solo el fragmento problemático, vuelve a escuchar sin leer y resume. Aumenta duración y variedad de voces gradualmente. La voz sintética elimina parte de la variación natural, por lo que no sirve para valorar por sí sola comprensión C1.',['Marca una afirmación explícita y dos inferencias con sus pistas.','Explica qué podría cambiar la conclusión del hablante.','Resume la postura final, no solo la introducción.'])],
chunks:['otra cosa es que','no niego… cuestiono','dicho esto','no se puede determinar'],
quiz:[q('«Según algunos, funciona; yo tengo dudas» atribuye confianza…','A otras personas, no necesariamente al hablante.',['Siempre al hablante.','A nadie en el texto.'],'La atribución y el contraste separan posturas.'),q('«Es barato; otra cosa es que nos convenga» expresa…','Reconocimiento del precio y reserva sobre su utilidad.',['Apoyo incondicional.','Negación de que sea barato.'],'La ventaja admitida no determina la recomendación final.'),q('Una inferencia sólida debería tener…','Una pista identificable en el discurso.',['Solo una intuición personal.','La misma palabra que la opción.'],'La evidencia limita la interpretación.'),q('Si la fuente no aclara la intención…','Puedes concluir que no se puede determinar.',['Debes inventar una intención.','La intención siempre es ironía.'],'La incertidumbre puede ser la interpretación correcta.'),q('Para entender una entrevista larga conviene anotar…','Tesis, razones, reservas y cambios de postura.',['Todas las palabras sin relaciones.','Solo los adjetivos.'],'Las relaciones permiten reconstruir el argumento.'),q('Una voz sintética basta para certificar escucha C1.','No.',['Sí, si se reproduce rápido.','Sí, si el texto es largo.'],'El habla auténtica incluye variación, prosodia e interacción que el TTS no reproduce plenamente.')],
speak:'Resume una entrevista real y distingue lo que la persona afirma, lo que concede y lo que deja abierto. Tu compañero pide evidencia para una de tus inferencias.',write:'Escribe una ficha de escucha con tesis, dos argumentos, una reserva y una inferencia justificada. Termina con una pregunta cuya respuesta no aparece en el audio.',model:'La entrevistada reconoce que la propuesta reduciría algunos desplazamientos, pero no la presenta como una solución completa. Su reserva principal se refiere a quienes no pueden modificar sus horarios. De su insistencia en ese grupo se puede inferir que considera insuficiente el diseño actual. No se puede determinar, sin embargo, qué alternativa concreta apoyaría.'},
{id:'c1-lectura',level:'C1',title:'Leer argumentos y evaluar su alcance',tag:'Lectura crítica',minutes:50,
goal:'Separar tesis, evidencia, supuestos y conclusión en textos complejos.',help:'An association is not automatically a cause. An anecdote illustrates a case; it does not establish the frequency of that case in a population.',
sections:[
s('Reconstruir el argumento','Identifica la pregunta que intenta responder el texto, su tesis y las razones que la sostienen. Una introducción puede exponer una creencia común para refutarla. Busca quién sostiene cada idea y qué información se presenta como evidencia. Un ejemplo ilustra; una cifra cuantifica; una comparación puede aclarar o distorsionar. No confundas complejidad verbal con calidad del razonamiento.',['La tesis responde a…','Este ejemplo ilustra…, pero no prueba…','La conclusión depende de que…']),
s('Supuestos y límites','Un argumento puede asumir que las personas tienen tiempo, recursos o intereses parecidos. Pregunta qué tendría que ser cierto para que la conclusión se sostuviera. Una asociación no demuestra por sí sola causalidad. Un cambio observado puede tener varias explicaciones. Señala límites de muestra, contexto o fecha cuando la fuente los ofrece; no inventes defectos estadísticos que no puedes comprobar.',['Los datos describen este grupo; no necesariamente toda la población.','No se puede atribuir el cambio únicamente a la medida.','Falta saber si el resultado se mantiene a largo plazo.']),
s('Vocabulario abstracto y cohesión','Interpreta referentes como dicha medida, ese planteamiento, lo anterior y tal circunstancia. Determina a qué oración apuntan. Descompón oraciones largas en verbo principal, sujeto y subordinadas. Lee con atención nominalizaciones: «la reducción del gasto» puede ocultar quién lo reduce. Reformula en una frase clara antes de decidir si has comprendido.',['Ese planteamiento = la propuesta recién presentada.','La implementación de la medida = aplicar la medida.','El texto contrapone una ventaja inmediata a un coste posterior.'])],
chunks:['la conclusión depende de','no necesariamente','cabe preguntarse','el texto presupone'],
quiz:[q('Una asociación entre dos hechos prueba por sí sola…','Ninguna relación causal definitiva.',['Que uno causa siempre el otro.','Que no existe ninguna relación.'],'La asociación requiere análisis adicional para inferir causalidad.'),q('Un ejemplo aislado puede…','Ilustrar un caso.',['Medir por sí solo su frecuencia general.','Demostrar una regla universal.'],'Una anécdota no determina la distribución de un fenómeno.'),q('Para interpretar «dicha medida» debes…','Identificar su antecedente en el texto.',['Traducir solo medida al inglés.','Ignorar la frase anterior.'],'El referente conecta partes del discurso.'),q('Una introducción que presenta una creencia común…','Puede anunciar una idea que después se refuta.',['Siempre expresa la tesis final.','No forma parte del argumento.'],'Hay que seguir el desarrollo completo.'),q('Una crítica rigurosa debería…','Señalar límites que se puedan justificar.',['Inventar un tamaño de muestra.','Rechazar todo texto con cifras.'],'La lectura crítica exige evidencia para la propia crítica.'),q('«La implementación de la medida» puede reformularse como…','Aplicar la medida.',['Eliminar cualquier medida.','Opinar sin actuar.'],'La nominalización presenta una acción como nombre.')],
speak:'Presenta el argumento de un artículo sin expresar aún tu opinión. Después indica un supuesto, una fortaleza y una limitación. Responde a una defensa del texto.',write:'Escribe una reseña crítica de 250 palabras. Dedica un párrafo al argumento del autor, uno a la evidencia y otro a tu evaluación justificada.',model:'El artículo defiende que la flexibilidad de horarios mejora la participación. Su ejemplo principal ilustra cómo algunas personas compatibilizan actividades, pero no permite saber cuántas se benefician. La conclusión parece asumir que todas tienen capacidad para cambiar su jornada. El argumento sería más convincente si distinguiera situaciones laborales y explicara cómo atender a quienes carecen de esa flexibilidad.'},
{id:'c1-escritura',level:'C1',title:'Escribir textos claros y revisar con criterio',tag:'Composición avanzada',minutes:55,
goal:'Planificar, desarrollar y revisar textos extensos con coherencia y un registro adecuado.',help:'A clear C1 text does not require ornate wording. Each paragraph should contribute to the purpose, with claims proportionate to evidence.',
sections:[
s('Propósito género y esquema','Decide si escribes un correo, informe, reseña o artículo de opinión. Define destinatario, propósito y dos o tres ideas centrales. Un informe puede presentar problema, opciones, valoración y propuesta; una reclamación, hechos, impacto y solución solicitada. Antes de redactar, asigna una función a cada párrafo. La extensión es una restricción de tarea, no una meta que justifique repeticiones.',['Problema → alternativas → valoración → recomendación.','Hecho → consecuencia → petición concreta.','Tesis → razón → objeción → conclusión.']),
s('Cohesión y precisión','Mantén tiempos y referentes consistentes. Repite un término cuando un pronombre resulte ambiguo; usa sinónimos solo si conservan el sentido. Evita frases con demasiadas subordinadas y nominalizaciones. Divide una oración cuando contenga varias afirmaciones que necesitan evidencia distinta. Al presentar datos, conserva el grado de certeza y atribuye la fuente.',['La propuesta ofrece dos ventajas. La primera…','Este resultado sugiere…, aunque no permite afirmar…','Recomiendo realizar una prueba antes de ampliar la medida.']),
s('Tres pasadas de revisión','Primera: cumplimiento de la tarea y organización. Segunda: precisión, concordancia, tiempos, preposiciones y referencias. Tercera: ortografía, tildes y puntuación. No separes sujeto y verbo con una coma sin motivo: «la propuesta, mejora» es incorrecto en ese patrón. Usa punto y coma con moderación y reserva los dos puntos para anunciar explicación, lista o cita según contexto. Lee en voz alta para detectar frases difíciles, pero comprueba también el sentido.',['¿He respondido a todos los puntos pedidos?','¿Se entiende quién hace cada acción?','¿Una conclusión dice más de lo que justifican mis razones?'])],
chunks:['convendría valorar','a la luz de','en estas condiciones','propongo que'],
quiz:[q('La primera revisión debería comprobar…','Propósito y cumplimiento de la tarea.',['Solo si hay palabras largas.','Solo las tildes del título.'],'Corregir forma no resuelve una tarea mal respondida.'),q('Elige la puntuación correcta.','La propuesta mejora el acceso.',['La propuesta, mejora el acceso.','La, propuesta mejora el acceso.'],'No se separa sujeto de verbo por una coma arbitraria.'),q('Si un pronombre resulta ambiguo…','Repite el nombre para aclarar.',['Añade otros tres pronombres.','Elimina toda referencia.'],'La claridad tiene prioridad sobre evitar cualquier repetición.'),q('Un sinónimo útil debe…','Mantener el sentido requerido por el contexto.',['Ser siempre más largo.','Cambiar el grado de certeza.'],'La sustitución no debe alterar el contenido.'),q('En un informe de recomendación necesitas…','Relacionar la propuesta con los criterios de valoración.',['Elegir sin explicar.','Repetir el título al final.'],'La decisión debe derivarse de lo analizado.'),q('Una conclusión bien ajustada…','No afirma más de lo que sostienen las razones.',['Siempre utiliza todos o nunca.','Necesita añadir un dato inventado.'],'El alcance de la conclusión debe corresponder a la evidencia.')],
speak:'Explica el esquema de un informe antes de escribirlo. Tu compañero pregunta por qué recomiendas una opción y qué dato podría cambiar tu decisión.',write:'Redacta un informe de 250–300 palabras para elegir entre tres actividades de aprendizaje. Usa como criterios tiempo, coste y oportunidades de conversación. Revisa en tres pasadas.',model:'Para elegir una actividad conviene valorar cuánto tiempo podemos dedicarle y qué oportunidades ofrece para hablar. La conversación semanal exige coordinación, pero permite practicar respuestas espontáneas. La escucha individual resulta más flexible, aunque necesita una tarea posterior de expresión. Recomiendo combinar ambas opciones y revisar el progreso tras cuatro semanas antes de ampliar el compromiso.'},
{id:'c1-negociar',level:'C1',title:'Sostener turnos largos y negociar',tag:'Interacción y soltura',minutes:45,
goal:'Desarrollar ideas, responder a cambios y alcanzar acuerdos sin perder precisión.',help:'Fluency includes managing turns, clarifying, reformulating and responding to another speaker. A memorized monologue alone cannot show interactive ability.',
sections:[
s('Organizar un turno sin recitar','Abre con la idea principal y anuncia el recorrido: veo dos dificultades. Desarrolla una, aporta un ejemplo y pasa a la siguiente. Si pierdes una palabra, reformula sin rehacer todo el turno. No confundas velocidad con fluidez: el ritmo útil permite seguir relaciones y referentes. Las pausas entre ideas pueden ayudar; observa cuáles se deben a organizar y cuáles a no recuperar formas básicas.',['Lo dividiría en dos partes.','Mejor dicho, lo que me preocupa es…','Volviendo a lo que comentabas…']),
s('Negociar intereses y restricciones','Distingue posiciones y necesidades: «quiero ir el sábado» puede responder a disponibilidad, precio o compañía. Pregunta por el motivo antes de ofrecer alternativas. Propón intercambios realistas y comprueba acuerdos parciales. No respondas a una restricción nueva con el mismo discurso preparado; adapta la propuesta.',['¿Qué es lo más importante para ti?','Si adelantamos la salida, ¿te encaja mejor?','Podemos mantener el lugar y cambiar la fecha.']),
s('Evaluar transferencia','Repite una tarea para mejorar, pero comprueba después con un tema nuevo. Graba, escucha y elige dos correcciones que tengan impacto. Compara claridad, pausas por búsqueda, variedad y respuesta al interlocutor, no solo número de palabras. Tu pareja puede facilitar conversación; una valoración precisa del nivel requiere muestras variadas y criterios aplicados por una persona capacitada. La autoevaluación de esta web orienta el estudio.',['Primera versión → dos mejoras → segunda versión → tema nuevo.','¿Respondí a la objeción o seguí con mi guion?','¿Pude explicar una palabra que no recordaba?'])],
chunks:['lo dividiría en','mejor dicho','volviendo a lo que comentabas','¿qué te encaja mejor?'],
quiz:[q('Para descubrir la necesidad detrás de una propuesta, pregunta…','¿Qué es lo más importante para ti?',['¿Por qué no aceptas sin más?','¿Podemos dejar de hablar?'],'La pregunta permite negociar sobre intereses.'),q('Hablar más rápido siempre demuestra más fluidez.','No.',['Sí, en cualquier contexto.','Solo si no se respira.'],'La fluidez incluye claridad, recuperación e interacción.'),q('Para comprobar transferencia conviene…','Usar una tarea nueva después de practicar.',['Repetir solo el mismo guion.','Leer siempre la respuesta modelo.'],'Una tarea nueva distingue aprendizaje de memorización.'),q('Una nueva restricción del interlocutor exige…','Adaptar la propuesta y comprobar viabilidad.',['Repetir la propuesta sin cambios.','Ignorar la restricción.'],'Negociar implica responder a información nueva.'),q('«Mejor dicho» sirve para…','Reformular con mayor precisión.',['Cambiar siempre de idioma.','Terminar una conversación.'],'El marcador permite ajustar el mensaje sin reiniciarlo.'),q('La autoevaluación de esta web…','Orienta la práctica y no certifica un nivel.',['Otorga un diploma DELE.','Sustituye toda interacción real.'],'No se ha validado como instrumento certificador.')],
speak:'Negocia una visita de tres días con presupuesto limitado. Tu compañero cambia una fecha y añade una necesidad. Mantén un turno de dos minutos y después intercambiad propuestas hasta llegar a un acuerdo.',write:'Escribe un resumen de 220 palabras de un acuerdo: necesidades, opciones descartadas, compromisos y asuntos pendientes. Distingue acuerdo y propuesta aún no confirmada.',model:'Hemos acordado mantener la visita de tres días y cambiar la salida al viernes por la tarde. La opción del tren resulta más barata, pero todavía tenemos que comprobar el último horario. Yo buscaré alojamiento y tú consultarás la disponibilidad. Hemos descartado la excursión más larga para dejar tiempo de descanso. La cena del sábado queda pendiente de confirmación.'}
);

lessons.push({id:'b2-emociones',level:'B2',title:'Expresar emociones y reaccionar',tag:'Relaciones y sentimientos',minutes:40,
goal:'Explicar cómo te afecta una situación, reaccionar y hablar de relaciones con precisión.',help:'Me preocupa… and me da vergüenza… place the cause as grammatical subject. Estoy aburrida describes how I feel; soy aburrida describes how others may experience me.',
sections:[
s('Lo que sientes y lo que lo provoca','Sentirse + adjetivo presenta una experiencia: me siento cómoda. Dar + nombre organiza otras sensaciones: me da vergüenza, me da pena, me da miedo. Con preocupar y molestar, lo que causa la emoción funciona como sujeto: me preocupan los plazos; me molesta el ruido. Para una valoración de un hecho subordinado, es frecuente que + subjuntivo: me alegra que estés mejor. Aprende el patrón completo para no traducir emociones como una lista de adjetivos.',['Me da vergüenza hablar delante de mucha gente.','Me preocupa que no lleguemos a tiempo.','Me siento más segura cuando puedo pedir aclaraciones.']),
s('Describir y valorar una reacción','Estoy aburrida indica una sensación; soy aburrida puede describir cómo resultas a otras personas. Una actividad emocionante causa emoción; una persona emocionada la siente. Contrasta cansada/cansado y cansino o agotador según lo que quieras decir: «es un trabajo cansado» puede ser natural en ciertos contextos, pero agotador hace explícito el efecto. Usa marcadores de intensidad sin exagerar: un poco, bastante, muy, demasiado. Explica la causa y qué ayudaría a cambiar la situación.',['La noticia fue emocionante y me dejó emocionada.','Me resulta difícil seguir una conversación tan rápida.','Estoy algo nerviosa, pero tengo ganas de intentarlo.']),
s('Relaciones y respuestas naturales','Llevarse bien con describe una relación; quedar con, concertar o tener un encuentro; conocer a, haber tratado a una persona; conocer de vista, reconocer sin una relación estrecha. Reacciona con qué alegría, qué pena, qué bien o vaya, según contexto y tono. Si alguien cuenta una dificultad, reconocer lo que siente antes de aconsejar puede facilitar la conversación. No necesitas estar de acuerdo con todo para mostrar que has entendido.',['Me llevo bien con mis compañeras.','La conozco de vista, pero nunca hemos hablado.','Qué pena; ¿quieres contarme qué pasó?'])],
chunks:['me da vergüenza','me resulta difícil','tengo ganas de','me llevo bien con'],
quiz:[q('Me ___ los plazos tan cortos.','preocupan',['preocupa','preocupáis'],'El sujeto los plazos es plural.'),q('Siento aburrimiento ahora: estoy ___.','aburrida',['aburrir','aburridamente'],'Estar + adjetivo describe la sensación.'),q('Me alegra que tú ___ mejor.','estés',['eres','estar'],'Una valoración introducida con que usa subjuntivo en este contexto.'),q('Para expresar una relación positiva, di…','Me llevo bien con ella.',['La quedo bien.','Me conozco bien con ella.'],'Llevarse bien con describe la relación.'),q('La reconozco, pero nunca hemos hablado: la conozco ___.','de vista',['por una charla larga','de quedar mucho'],'Conocer de vista implica reconocimiento sin trato cercano.'),q('Tengo ganas ___ intentarlo.','de',['a','para'],'Tener ganas de mantiene la preposición ante infinitivo.')],
speak:'Cuenta una situación que te pone nerviosa y otra en la que te sientes cómoda. Tu compañero comparte una dificultad y tú respondes mostrando comprensión antes de proponer ayuda.',write:'Escribe 180 palabras sobre cómo ha cambiado tu confianza al hablar español. Incluye sensaciones, causas y una relación que haya ayudado a practicar.',model:'Antes me daba vergüenza preguntar cuando no entendía algo. Me preocupaba que las demás personas perdieran la paciencia. Ahora me siento más cómoda y tengo ganas de participar. Me llevo bien con mis compañeras y me alegra que me den tiempo para explicar mis ideas. Todavía me resulta difícil seguir conversaciones de grupo, pero puedo pedir una aclaración.'});

// Rotación determinista de opciones para que la respuesta no ocupe siempre el mismo lugar.
for(const [id,visual] of Object.entries({'b1-base':'identity','b1-presente':'gustar','b1-pasados':'time','b1-pronombres':'pronouns'}))lessons.find(l=>l.id===id).visual=visual;
lessons.push(...a2Lessons);
lessons.forEach((lesson,i)=>lesson.quiz.forEach((item,j)=>{
  const whyEn=lessonQuizEnglish[lesson.id]?.[j];
  if(whyEn)item.whyEn=whyEn;
  const shift=(i+j)%item.options.length;
  item.options=[...item.options.slice(shift),...item.options.slice(0,shift)];
  item.answer=(item.options.length-shift)%item.options.length;
}));

